import numpy as np
def equation(t, x, v, params):
    w = 0.4645
    C = np.cos(w*t); S = np.sin(w*t)
    return (params[0] + params[1]*np.tanh(v) + params[2]*np.exp(-x) + params[3]*C*np.tanh(v)
            + params[4]*x**params[9] + params[5]/v + params[6]*S + params[7]*x + params[8]*v)
